    /** The status of a protocol code. */
    static ofCode(code: number): HapiTransactionStatus {
        const status = HapiTransactionStatus.#BY_CODE.get(code);
        if (status === undefined) {
            throw new RangeError(`Unknown transaction status code: ${code}`);
        }
        return status;
    }

    toString(): string {
        return this.#name;
    }
